#include "dome/document.hpp"
#include <nlohmann/json.hpp>
#include <iostream>
#include <new>
#include <cstdlib>
#include <tuple>
namespace {thread_local bool injecting=false,denied=false;thread_local size_t allocations=0,boundary=SIZE_MAX;}
[[gnu::noinline]]void *operator new(size_t n){if(injecting&&++allocations>=boundary){denied=true;throw std::bad_alloc();}if(auto p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
[[gnu::noinline]]void *operator new[](size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}void operator delete[](void*p,size_t)noexcept{std::free(p);}
namespace dome {struct DocumentTransactionTestAccess {static auto tokens(const Document &d){std::lock_guard lock(d.model_mutex_);return std::tuple{d.content_,d.next_content_,d.saved_content_,d.undo_.size(),d.redo_.size(),d.state_.generation,d.state_.revision,d.state_.edit_authority,d.state_.view_epoch,d.state_.input_epoch,d.state_.expressions,d.asset_work_.load(),d.native_source_scene_,d.input_.menu_open(),d.input_.menu_page(),d.input_.menu_index(),d.input_.menu_device()};}};}
using namespace dome;
void ready(Document &d){if(!d.wait_mesh(std::chrono::seconds(90))||!d.frame().state->error.empty())throw std::runtime_error("Preview fault endpoint: "+d.frame().state->error);}
void prepare(Document &d,const Scene &base,int op){d.replace(base.snapshot());ready(d);if(op){d.begin_expression_preview();ready(d);if(op>=2){const auto v=d.frame().state->expressions;d.configure_expression_preview(0,.35f,v->session);ready(d);}}}
void action(Document &d,int op){if(!op)d.begin_expression_preview();else{const auto v=d.frame().state->expressions;if(op==1)d.configure_expression_preview(0,.35f,v->session);else d.end_expression_preview(op==3,v->session);}}
void completed(Document &d,const Scene &base,int op){if(op==3){if(!d.wait_asset(std::chrono::seconds(90)))throw std::runtime_error("Apply fault endpoint timeout");ready(d);if(!d.undo()||d.copy_scene().encode()!=base.encode()||!d.redo())throw std::runtime_error("Retry did not remain one exact undoable Apply");}else ready(d);}
int main(int argc,char **argv)try{if(argc!=2)return 2;const auto base=Scene::load(argv[1]);const auto exact=base.encode();size_t total=0;for(int op=0;op<4;++op){size_t count=0;for(int repeat=0;repeat<2;++repeat){Document d;prepare(d,base,op);boundary=SIZE_MAX;allocations=0;injecting=true;try{action(d,op);}catch(...){injecting=false;throw;}injecting=false;const auto n=allocations;completed(d,base,op);if(!n||(repeat&&n!=count))throw std::runtime_error("Actual repeated native admission allocation count is not stable");count=n;}std::cout<<"ADMISSION operation="<<op<<" allocations="<<count<<std::endl;for(size_t at=1;at<=count;++at){Document d;prepare(d,base,op);const auto scene=d.copy_scene().encode();const auto tokens=DocumentTransactionTestAccess::tokens(d);const auto publication=d.frame().state;allocations=0;boundary=at;denied=false;bool caught=false;injecting=true;try{action(d,op);}catch(const std::bad_alloc&){caught=true;}injecting=false;if(!caught||!denied||d.copy_scene().encode()!=scene||DocumentTransactionTestAccess::tokens(d)!=tokens||d.frame().state!=publication){std::cerr<<"FAILED_PREFIX operation="<<op<<" boundary="<<at<<" caught="<<caught<<" denied="<<denied<<std::endl;throw std::runtime_error("Native expression admission failure changed exact source/session/input/history/publication");}action(d,op);completed(d,base,op);++total;}std::cout<<"COMPLETE operation="<<op<<" prefixes="<<count<<std::endl;}if(base.encode()!=exact)throw std::runtime_error("Immutable original changed");std::cout<<"PASS native_expression_admission_prefixes="<<total<<std::endl;return 0;}catch(const std::exception &e){injecting=false;std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
